static void power_off_pass_event_cb(struct _lv_timer_t *timer)
{
    if (power_off_pass_timer) {
        lv_timer_del(power_off_pass_timer);
        power_off_pass_timer = NULL;
        pwr_key_power_off();
        }
}


void power_off_pass_timer_start(uint32_t time)
{

    if (power_off_pass_timer == NULL) {
        power_off_pass_timer = lv_timer_create(power_off_pass_event_cb,time,0);
        }

}


void power_off_app_pass_ui_event_actions(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    //lv_obj_t * target = lv_event_get_target(e);
    //	__inf("power_off_app_pass_ui_event_actions 00 =%d\r\n",event_code);
    switch (event_code)
    {
        case LV_EVENT_SCREEN_LOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_add_obj(lv_group_get_default(),obj);
                    lv_group_focus_obj(obj);
                    }

                }
            break;

        case LV_EVENT_SCREEN_UNLOADED:
            {
                lv_obj_t *      obj = e->user_data;

                if (obj) {
                    lv_group_remove_obj(obj);
                    }
                }
            break;

        default:
            break;
        }
}


